package com.booktracker.dao;

import com.booktracker.model.*;
import com.booktracker.util.DBUtil;
import java.sql.*; import java.util.*;

public class TrackerDAO {
 public List<Book> books() throws SQLException { List<Book> out=new ArrayList<>(); String q="SELECT id,title,author,isbn,total_copies,available_copies FROM books ORDER BY title"; try(Connection c=DBUtil.getConnection(); PreparedStatement p=c.prepareStatement(q); ResultSet r=p.executeQuery()){while(r.next())out.add(new Book(r.getInt("id"),r.getString("title"),r.getString("author"),r.getString("isbn"),r.getInt("total_copies"),r.getInt("available_copies")));} return out; }
 public List<Borrower> borrowers() throws SQLException { List<Borrower> out=new ArrayList<>(); try(Connection c=DBUtil.getConnection(); PreparedStatement p=c.prepareStatement("SELECT id,full_name,email,phone FROM borrowers ORDER BY full_name"); ResultSet r=p.executeQuery()){while(r.next())out.add(new Borrower(r.getInt("id"),r.getString("full_name"),r.getString("email"),r.getString("phone")));} return out; }
 public List<Issue> issues() throws SQLException { List<Issue> out=new ArrayList<>(); String q="SELECT i.id,i.book_id,i.borrower_id,i.issue_date,i.due_date,i.return_date,i.status,b.title book_title,br.full_name borrower_name FROM issues i JOIN books b ON b.id=i.book_id JOIN borrowers br ON br.id=i.borrower_id ORDER BY i.id DESC"; try(Connection c=DBUtil.getConnection();PreparedStatement p=c.prepareStatement(q);ResultSet r=p.executeQuery()){while(r.next())out.add(new Issue(r.getInt("id"),r.getInt("book_id"),r.getInt("borrower_id"),r.getString("book_title"),r.getString("borrower_name"),r.getDate("issue_date").toString(),r.getDate("due_date").toString(),r.getDate("return_date")==null?"—":r.getDate("return_date").toString(),r.getString("status")));}return out; }
 public void addBook(String title,String author,String isbn,int copies) throws SQLException { try(Connection c=DBUtil.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO books(title,author,isbn,total_copies,available_copies) VALUES(?,?,?,?,?)")){p.setString(1,title.trim());p.setString(2,author.trim());p.setString(3,blankNull(isbn));p.setInt(4,copies);p.setInt(5,copies);p.executeUpdate();} }
 public void addBorrower(String name,String email,String phone) throws SQLException { try(Connection c=DBUtil.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO borrowers(full_name,email,phone) VALUES(?,?,?)")){p.setString(1,name.trim());p.setString(2,blankNull(email));p.setString(3,blankNull(phone));p.executeUpdate();} }
 public void issueBook(int bookId,int borrowerId,java.sql.Date issue,java.sql.Date due) throws SQLException { Connection c=DBUtil.getConnection(); try { c.setAutoCommit(false); try(PreparedStatement p=c.prepareStatement("UPDATE books SET available_copies=available_copies-1 WHERE id=? AND available_copies>0")){p.setInt(1,bookId);if(p.executeUpdate()!=1)throw new SQLException("No copies available for this book.");} try(PreparedStatement p=c.prepareStatement("INSERT INTO issues(book_id,borrower_id,issue_date,due_date,status) VALUES(?,?,?,?, 'ISSUED')")){p.setInt(1,bookId);p.setInt(2,borrowerId);p.setDate(3,issue);p.setDate(4,due);p.executeUpdate();} c.commit(); } catch(SQLException e){try{c.rollback();}catch(SQLException ignored){} throw e;} finally {try{c.setAutoCommit(true);}finally{c.close();}} }
 public void returnBook(int issueId) throws SQLException { Connection c=DBUtil.getConnection(); try {c.setAutoCommit(false); int bookId; try(PreparedStatement p=c.prepareStatement("SELECT book_id,status FROM issues WHERE id=? FOR UPDATE")){p.setInt(1,issueId);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("Issue record not found.");if("RETURNED".equals(r.getString("status")))throw new SQLException("This book has already been returned.");bookId=r.getInt("book_id");}} try(PreparedStatement p=c.prepareStatement("UPDATE issues SET status='RETURNED',return_date=CURRENT_DATE WHERE id=?")){p.setInt(1,issueId);p.executeUpdate();} try(PreparedStatement p=c.prepareStatement("UPDATE books SET available_copies=available_copies+1 WHERE id=?")){p.setInt(1,bookId);p.executeUpdate();} c.commit();}catch(SQLException e){try{c.rollback();}catch(SQLException ignored){}throw e;}finally{try{c.setAutoCommit(true);}finally{c.close();}} }
 public int count(String table) throws SQLException { if(!Arrays.asList("books","borrowers","issues").contains(table))throw new SQLException("Invalid table");try(Connection c=DBUtil.getConnection();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*) FROM "+table)){r.next();return r.getInt(1);} }
 private String blankNull(String s){return s==null||s.trim().isEmpty()?null:s.trim();}
}
